__d(function(g,r,_i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),e.sampleRecipes=function(s){return('fr'===s?t:i).map((t,i)=>({...(0,n.parseRecipeText)(t,{sourceType:'manual'}),tags:[['v\xe9g\xe9tarien','vegan'],['dessert'],['v\xe9g\xe9tarien','rapide']][i].map(n=>'en'===s?{"v\xe9g\xe9tarien":'vegetarian',rapide:'quick'}[n]??n:n)}))};var n=r(d[0]);const t=["Dahl de lentilles corail\nPour 4 personnes \xb7 Pr\xe9paration : 10 min \xb7 Cuisson : 25 min\nIngr\xe9dients\n250 g de lentilles corail\n1 oignon\n2 gousses d'ail\n1 morceau de gingembre (3 cm)\n1 c. \xe0 soupe de curry en poudre\n40 cl de lait de coco\n1 bo\xeete de tomates concass\xe9es (400 g)\n50 cl d'eau\n1 citron vert\n1 c. \xe0 soupe d'huile d'olive\nSel\n\xc9tapes\n1. \xc9mincez l'oignon, l'ail et le gingembre.\n2. Faites-les revenir 5 min dans l'huile avec le curry.\n3. Ajoutez les lentilles rinc\xe9es, les tomates, le lait de coco et l'eau.\n4. Laissez mijoter 20 minutes en remuant de temps en temps.\n5. Salez, pressez le citron vert et servez avec du riz ou du pain naan.","Cr\xeapes de la Chandeleur\nPour 4 personnes \xb7 Pr\xe9paration : 10 min \xb7 Cuisson : 20 min\nIngr\xe9dients\n250 g de farine\n4 \u0153ufs\n50 cl de lait\n30 g de beurre fondu\n1 c. \xe0 soupe de sucre\n1 pinc\xe9e de sel\n\xc9tapes\n1. M\xe9langez la farine, le sucre et le sel dans un saladier.\n2. Creusez un puits, ajoutez les \u0153ufs et fouettez en versant le lait petit \xe0 petit.\n3. Incorporez le beurre fondu et laissez reposer la p\xe2te 30 minutes.\n4. Faites cuire les cr\xeapes 1 minute de chaque c\xf4t\xe9 dans une po\xeale bien chaude.","Salade de pois chiches, feta et concombre\nPour 2 personnes \xb7 Pr\xe9paration : 15 min\nIngr\xe9dients\n1 bo\xeete de pois chiches (400 g)\n1 concombre\n200 g de tomates cerises\n100 g de feta\n1/2 oignon rouge\n1 bouquet de persil\n2 c. \xe0 soupe d'huile d'olive\n1 citron\nSel, poivre\n\xc9tapes\n1. Rincez et \xe9gouttez les pois chiches.\n2. Coupez le concombre en d\xe9s, les tomates en deux et \xe9mincez l'oignon.\n3. M\xe9langez le tout avec la feta \xe9miett\xe9e et le persil cisel\xe9.\n4. Assaisonnez avec l'huile, le jus du citron, le sel et le poivre."],i=["Red lentil dahl\nServes 4 \xb7 Prep: 10 min \xb7 Cook: 25 min\nIngredients\n250 g red lentils\n1 onion\n2 cloves garlic\n1 piece ginger (3 cm)\n1 tbsp curry powder\n400 ml coconut milk\n1 can chopped tomatoes (400 g)\n500 ml water\n1 lime\n1 tbsp olive oil\nSalt\nMethod\n1. Chop the onion, garlic and ginger.\n2. Fry them for 5 min in the oil with the curry powder.\n3. Add the rinsed lentils, tomatoes, coconut milk and water.\n4. Simmer for 20 minutes, stirring now and then.\n5. Season, squeeze over the lime and serve with rice or naan.","Simple pancakes\nServes 4 \xb7 Prep: 10 min \xb7 Cook: 20 min\nIngredients\n250 g flour\n4 eggs\n500 ml milk\n30 g melted butter\n1 tbsp sugar\n1 pinch of salt\nMethod\n1. Mix the flour, sugar and salt in a bowl.\n2. Make a well, add the eggs and whisk while pouring in the milk little by little.\n3. Stir in the melted butter and let the batter rest for 30 minutes.\n4. Cook the pancakes 1 minute on each side in a very hot pan.","Chickpea, feta and cucumber salad\nServes 2 \xb7 Prep: 15 min\nIngredients\n1 can chickpeas (400 g)\n1 cucumber\n200 g cherry tomatoes\n100 g feta\n1/2 red onion\n1 bunch parsley\n2 tbsp olive oil\n1 lemon\nSalt, pepper\nMethod\n1. Rinse and drain the chickpeas.\n2. Dice the cucumber, halve the tomatoes and slice the onion.\n3. Mix everything with the crumbled feta and chopped parsley.\n4. Dress with the oil, lemon juice, salt and pepper."]},781,[789]);